# Runtime v2 · LZ Lazy list bên trong: compose theo nhu cầu, key, contentType, dùng lại slot (chương mới)
# Nguồn: "Lists and grids" (developer.android.com, đọc 2026-11-23; phần Tips chỉ có bản tóm tắt); LazyLayout.kt, LazyLayoutItemContentFactory.kt,
# LazySaveableStateHolder.kt (foundation), SubcomposeLayout.kt (ui) @296313a4; Jetpack Compose by Tutorials Ch.4; Essentials Ch.34–37.

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim runtime.lazy ----------------
    m = lambda k, vi, en=None: a('m.lazy.' + k, vi, en)
    m('title', 'Cuộn một danh sách: mục nào được compose, slot nào được dùng lại?', 'Scrolling a list: which items get composed, which slots get reused?')
    m('overview', 'Danh sách 20 mục, màn hình vừa 4 mục. Cuộn ba lần, mỗi lần một mục rời mép trên và một mục mới vào mép dưới. So ba cách: `LazyColumn` với mọi mục cùng kiểu, `LazyColumn` mà các mục mới khác `contentType` với mục cũ, và `Column` + `verticalScroll`.', 'A list of 20 items, a screen that fits 4. Scroll three times; each time one item leaves the top edge and a new one enters at the bottom. Compare three ways: a `LazyColumn` where every item has the same type, a `LazyColumn` where the new items have a different `contentType` from the old ones, and a `Column` + `verticalScroll`.')
    m('wrapup', '`LazyColumn` chỉ compose mục đang cần, ngay trong bước đo (nó là một `SubcomposeLayout`). Mục rời màn hình không bị hủy ngay: slot của nó vào một pool (tối đa 7 slot cho mỗi `contentType` ở commit ghim), và mục mới CÙNG `contentType` được compose vào slot đó thay vì tạo từ đầu. `Column` + `verticalScroll` thì compose mọi mục ngay từ đầu; cuộn chỉ đổi vị trí. Với danh sách dài hay không biết trước độ dài, lazy là lựa chọn mặc định.', '`LazyColumn` composes only the items it needs, right in the measure step (it is a `SubcomposeLayout`). An item that leaves the screen is not destroyed right away: its slot goes into a pool (up to 7 slots per `contentType` at the pinned commit), and a new item with the SAME `contentType` is composed into that slot instead of from scratch. `Column` + `verticalScroll` composes every item up front; scrolling only changes positions. For long or unknown-length lists, lazy is the default choice.')
    m('simp.1', 'Mô hình bỏ qua prefetch (lazy list có thể compose trước mục sắp xuất hiện giữa các frame) và cache window, nên số compose mới thật có thể sớm hơn. Mỗi lần cuộn đúng một mục; danh sách thật có thể đi qua nhiều mục trong một frame.', 'The model ignores prefetching (a lazy list may compose upcoming items ahead of time between frames) and the cache window, so real new compositions can happen earlier. Each scroll moves exactly one item; a real list may pass several items in one frame.')
    m('simp.2', 'Thứ tự theo mã `SubcomposeLayout` ở commit ghim: slot thôi được dùng chỉ vào pool ở CUỐI lượt đo, nên trong frame cuộn đầu tiên pool còn rỗng và mục mới phải compose từ đầu.', 'The order follows the `SubcomposeLayout` code at the pinned commit: slots stop being used and go into the pool only at the END of a measure pass, so in the first scroll frame the pool is still empty and the new item must be composed from scratch.')
    m('ctl.hint', 'Chạy "cùng kiểu" trước, rồi "khác contentType", cuối cùng là Column.', 'Run "same type" first, then "different contentType", then the Column.')
    m('ctl.which', 'Cách viết danh sách', 'How the list is written')
    for k, vi, en in [('same', 'LazyColumn, mọi mục cùng kiểu', 'LazyColumn, every item the same type'), ('types', 'LazyColumn, mục mới khác contentType', 'LazyColumn, new items of another contentType'), ('column', 'Column cuộn bằng verticalScroll', 'Column scrolled with verticalScroll')]:
        m('ctl.which.' + k, vi, en)
    m('diagramTitle', 'Dữ liệu, khối đo của lazy layout, slot đang hiện và pool', 'Data, the lazy layout\'s measure block, active slots and the pool')
    m('diagramDesc', 'Dữ liệu đi vào khối đo; khối đo compose slot đang hiện; slot rời màn hình vào pool, và slot trong pool có thể quay lại phục vụ mục mới', 'Data flows into the measure block; the measure block composes the active slots; slots leaving the screen go into the pool, and a pooled slot can come back to serve a new item')
    for k, vi, en in [('data', 'Danh sách 20 mục', 'List of 20 items'), ('measure', 'Khối đo (SubcomposeLayout)', 'Measure block (SubcomposeLayout)'), ('active', 'Slot đang hiện', 'Active slots'), ('pool', 'Pool dùng lại', 'Reuse pool')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('composed', 'Lần compose mục', 'Item compositions'), ('fresh', 'Compose từ đầu', 'From scratch'), ('reused', 'Dùng lại slot', 'Slots reused'), ('pool', 'Slot trong pool', 'Slots in pool')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('active', 'Mục đang hiện', 'Visible items'), ('pool', 'Pool', 'Pool'), ('op', 'Thao tác gần nhất', 'Latest operation')]:
        m('st.' + k, vi, en)
    S = [
        ('intro.same', 'LazyColumn, mọi mục cùng kiểu', 'A LazyColumn, every item the same type', '`items(messages, key = { it.id })` không khai báo `contentType`, nên mọi mục có cùng kiểu (null) và slot nào cũng hợp với mục nào.', '`items(messages, key = { it.id })` declares no `contentType`, so every item has the same type (null) and any slot fits any item.'),
        ('intro.types', 'LazyColumn với hai contentType', 'A LazyColumn with two contentTypes', 'Mục 0–3 là "text", từ mục 4 là "image". `contentType = { it.type }` báo cho lazy layout biết hai loại có cấu trúc khác nhau.', 'Items 0–3 are "text", from item 4 on they are "image". `contentType = { it.type }` tells the lazy layout the two kinds have different structures.'),
        ('intro.column', 'Column cuộn bằng verticalScroll', 'A Column scrolled with verticalScroll', 'Một `Column` cuộn được, lặp `forEach` qua 20 mục. Không có gì "lười" ở đây.', 'A scrollable `Column` looping `forEach` over 20 items. Nothing is lazy here.'),
        ('first', 'Lần đầu: compose 4 mục đang hiện', 'First pass: compose the 4 visible items', 'Trong bước đo, lazy layout compose từng mục cho tới khi lấp đầy viewport: mục 0–3. 16 mục còn lại chưa hề được compose.', 'During measurement the lazy layout composes items one by one until the viewport is full: items 0–3. The other 16 items have not been composed at all.'),
        ('col.first', 'Lần đầu: compose cả 20 mục', 'First pass: compose all 20 items', '`Column` compose và đo mọi con, dù chỉ 4 mục thấy được. Tài liệu: Column "can cause performance issues" với danh sách lớn vì mọi mục đều được compose và layout.', '`Column` composes and measures every child, even though only 4 are visible. The docs: Column "can cause performance issues" for large lists because every item is composed and laid out.'),
        ('col.scroll', 'Cuộn lần {n}: không compose gì', 'Scroll {n}: nothing composed', 'Cuộn chỉ đổi độ lệch khi đặt con; mọi mục đã có sẵn.', 'Scrolling only changes the placement offset; every item already exists.'),
        ('new1', 'Cuộn lần 1: mục {enter} compose từ đầu', 'Scroll 1: item {enter} composed from scratch', 'Mục {enter} cần hiện nhưng pool còn rỗng, nên phải compose mới. Cuối lượt đo, slot của mục {leave} (vừa rời mép trên) không còn dùng và được đưa vào pool thay vì hủy.', 'Item {enter} must appear but the pool is still empty, so it is composed anew. At the end of the measure pass, the slot of item {leave} (which just left the top) is no longer used and goes into the pool instead of being destroyed.'),
        ('reuse', 'Cuộn: mục {enter} dùng lại slot cũ', 'Scroll: item {enter} reuses an old slot', 'Slot trong pool cùng `contentType` với mục {enter}, nên nội dung của mục {enter} được compose VÀO slot đó: dùng lại LayoutNode và composition, ít việc hơn tạo mới. Slot của mục {leave} vào pool.', 'The pooled slot has the same `contentType` as item {enter}, so item {enter}\'s content is composed INTO that slot: the LayoutNode and composition are reused, less work than creating new ones. Item {leave}\'s slot goes into the pool.'),
        ('newType', 'Cuộn: mục {enter} không dùng lại được', 'Scroll: item {enter} cannot reuse', 'Pool chỉ có slot "text", còn mục {enter} là "image": khác `contentType` nên không tương thích, phải compose từ đầu. Slot "text" của mục {leave} vào pool.', 'The pool only has "text" slots and item {enter} is an "image": different `contentType`, not compatible, so it is composed from scratch. Item {leave}\'s "text" slot goes into the pool.'),
        ('end.same', 'Kết thúc: 5 compose mới, 2 dùng lại', 'The end: 5 fresh compositions, 2 reuses', 'Từ frame cuộn thứ hai, mỗi mục mới lấy slot của mục vừa rời đi.', 'From the second scroll frame on, each new item takes the slot of the item that just left.'),
        ('end.types', 'Kết thúc: 7 compose mới, 0 dùng lại', 'The end: 7 fresh compositions, 0 reuses', 'Ba slot "text" nằm chờ trong pool cho tới khi có mục "text" quay lại (hoặc bị bỏ khi pool đầy).', 'Three "text" slots wait in the pool until a "text" item comes back (or are dropped when the pool is full).'),
        ('end.column', 'Kết thúc: 20 mục đã compose ngay từ đầu', 'The end: 20 items composed up front', 'Với 20 mục thì chịu được; với 1000 mục ảnh như ví dụ của Essentials thì không.', 'With 20 items it is bearable; with 1000 photo items, as in the Essentials example, it is not.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('reuse', '`LazyLayoutItemReusePolicy.areCompatible` ở commit ghim chỉ so `contentType` của hai slot. [[src:fd-lazylayout-src]]', '`LazyLayoutItemReusePolicy.areCompatible` at the pinned commit only compares the two slots\' `contentType`. [[src:fd-lazylayout-src]]'),
        ('types', 'Tài liệu: Compose chỉ dùng lại composition giữa các mục cùng loại; khai báo `contentType` khi danh sách có nhiều loại mục. [[src:cp-lists]]', 'The docs: Compose only reuses compositions between items of the same type; declare `contentType` when a list has several kinds of items. [[src:cp-lists]]'),
        ('end.same', 'Pool giữ tối đa 7 slot mỗi loại, "giống RecyclerView": 5 (DEFAULT_MAX_SCRAP) + 2 (DEFAULT_CACHE_SIZE), theo chú thích trong mã. [[src:fd-lazylayout-src]]', 'The pool keeps up to 7 slots per type, "the same as RecyclerView": 5 (DEFAULT_MAX_SCRAP) + 2 (DEFAULT_CACHE_SIZE), per the code comment. [[src:fd-lazylayout-src]]'),
        ('end.types', 'Không khai báo `contentType` thì mọi mục cùng kiểu null: slot "text" có thể bị dùng cho mục "image", vẫn đúng nhưng phần lớn cây phải dựng lại. [[src:fd-lazylayout-src]] [[src:cp-lists]]', 'Without `contentType`, every item has the same null type: a "text" slot may be used for an "image" item, which is still correct but most of the tree must be rebuilt. [[src:fd-lazylayout-src]] [[src:cp-lists]]'),
        ('end.column', 'Tài liệu: lazy component "only compose and lay out items which are visible in the component\'s viewport". [[src:cp-lists]]', 'The docs: lazy components "only compose and lay out items which are visible in the component\'s viewport". [[src:cp-lists]]')]:
        m('co.' + k, vi, en)
    a('cap.lazy', 'Từ trái sang phải: dữ liệu, khối đo của lazy layout, slot đang hiện, pool dùng lại. Mũi tên khối đo → slot là compose từ đầu; slot → pool là mục vừa rời màn hình; mũi tên vòng từ pool về slot là dùng lại.', 'Left to right: the data, the lazy layout’s measure block, the active slots, the reuse pool. The measure → slot arrow is a fresh composition; slot → pool is an item that just left the screen; the arrow looping back from the pool to the slots is a reuse.')

    # ---------------- chương LZ (mới) ----------------
    C = 'lz'
    a(C + '.title', 'Lazy list bên trong: compose theo nhu cầu, key, contentType và dùng lại slot', 'Lazy lists inside: composing on demand, keys, contentType and slot reuse')
    a(C + '.essence',
      '`Column` lặp qua 1000 mục sẽ compose và đo cả 1000. `LazyColumn`/`LazyRow`/`LazyVerticalGrid` chỉ compose mục nằm trong viewport, ngay trong bước đo: bên dưới là một `SubcomposeLayout` (chương LO). Nội dung khai báo qua DSL `LazyListScope` (`item`, `items`, `stickyHeader`), không phải lambda `@Composable` thường.\n'
      'Ba thứ quyết định một lazy list chạy đúng và nhanh. `key` gắn state (`remember`, `rememberSaveable`) với MỤC thay vì VỊ TRÍ, nên thêm/xóa/sắp xếp không làm state nhảy sang mục khác (nối chương B3). `contentType` cho biết slot nào dùng lại được cho mục nào. Và đọc vị trí cuộn đúng cách (`derivedStateOf`, chương B4) để không recompose mỗi pixel.\n'
      'Chương đối chiếu sách với mã ở commit ghim: lazy list có một pool dùng lại slot, giống RecyclerView về con số, dù cơ chế là composition.',
      'A `Column` looping over 1000 items composes and measures all 1000. `LazyColumn`/`LazyRow`/`LazyVerticalGrid` compose only the items inside the viewport, right in the measure step: underneath is a `SubcomposeLayout` (chapter LO). Content is declared through the `LazyListScope` DSL (`item`, `items`, `stickyHeader`), not an ordinary `@Composable` lambda.\n'
      'Three things decide whether a lazy list is correct and fast. `key` ties state (`remember`, `rememberSaveable`) to the ITEM rather than the POSITION, so adding, removing or sorting does not make state jump to another item (linking chapter B3). `contentType` says which slot can be reused for which item. And reading the scroll position the right way (`derivedStateOf`, chapter B4) avoids recomposing on every pixel.\n'
      'The chapter checks the books against the code at the pinned commit: lazy lists have a slot-reuse pool, numerically like RecyclerView\'s, even though the mechanism is composition.')
    a(C + '.goal.g1', 'Đã thấy lần compose đầu tiên của danh sách', 'Saw the list\'s first composition')
    a(C + '.goal.g2', 'Đã chạy một cách viết danh sách tới cuối', 'Ran one way of writing the list to the end')
    a(C + '.sim.runtime.lazy', 'Compose và dùng lại khi cuộn', 'Composing and reusing while scrolling')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'Mỗi hàng của một `LazyColumn` có một ô checkbox giữ bằng `var checked by remember { mutableStateOf(false) }`. Bạn tick hàng thứ 3 rồi chèn một tin nhắn mới lên ĐẦU danh sách. Không khai báo `key`. Ô nào đang được tick?', 'Each row of a `LazyColumn` has a checkbox kept with `var checked by remember { mutableStateOf(false) }`. You tick the 3rd row, then insert a new message at the TOP of the list. No `key` is declared. Which box is ticked now?')
    B(C, S, 1, 'ans', 'Ô ở VỊ TRÍ thứ 3, lúc này là tin nhắn khác (tin bạn tick đã trôi xuống vị trí 4). Mặc định state của mục gắn với vị trí; tài liệu nói mục đổi vị trí "effectively lose any remembered state". Khai báo `key = { it.id }` thì state đi theo tin nhắn. [[src:cp-lists]]', 'The box at POSITION 3, which is now a different message (the one you ticked moved to position 4). By default an item\'s state is tied to its position; the docs say items that move "effectively lose any remembered state". Declare `key = { it.id }` and the state follows the message. [[src:cp-lists]]')

    S = 'why'
    a(C + '.sec.%s.title' % S, 'Column hay LazyColumn', 'Column or LazyColumn')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Essentials Ch.34: danh sách tạo bằng `Row`/`Column` tạo MỌI mục lúc khởi tạo, bất kể bao nhiêu mục thấy được. Với 1000 ảnh, máy sẽ sớm chạm giới hạn bộ nhớ và hiệu năng. `Column` cũng không tự cuộn: cần `Modifier.verticalScroll(rememberScrollState())`, và cuộn bằng mã dùng pixel (`scrollTo`, `animateScrollTo`, `maxValue`). Lazy list cuộn sẵn, và cuộn bằng mã theo CHỈ SỐ mục (`scrollToItem`, `animateScrollToItem`); cả bốn hàm đều là `suspend`, gọi trong `rememberCoroutineScope().launch`. [[src:book-compose-ess]] [[src:cp-lists]]', 'Essentials Ch.34: a list built with `Row`/`Column` creates EVERY item at initialisation, however many are visible. With 1000 photos the device quickly hits memory and performance limits. A `Column` does not scroll by itself either: it needs `Modifier.verticalScroll(rememberScrollState())`, and programmatic scrolling works in pixels (`scrollTo`, `animateScrollTo`, `maxValue`). A lazy list scrolls out of the box, and programmatic scrolling uses item INDICES (`scrollToItem`, `animateScrollToItem`); all four are `suspend` functions, called inside `rememberCoroutineScope().launch`. [[src:book-compose-ess]] [[src:cp-lists]]')
    B(C, S, 2, 'p', 'Tài liệu: với danh sách ngắn, cố định, cứ dùng `Column`/`Row` với `forEach`; với danh sách lớn hoặc không biết độ dài, `Column` có thể gây vấn đề hiệu năng vì mọi mục đều được compose và layout dù có thấy hay không. Lazy component "follow the same set of principles" như RecyclerView. Tutorials Ch.4 nói cùng ý: cột cuộn được hợp với nội dung tĩnh, còn dữ liệu động lớn thì dùng lazy. [[src:cp-lists]] [[src:book-compose-tut]]', 'The docs: for short, fixed lists, just use `Column`/`Row` with `forEach`; for large or unknown-length lists, `Column` can cause performance issues because every item is composed and laid out whether visible or not. Lazy components "follow the same set of principles" as RecyclerView. Tutorials Ch.4 makes the same point: scrollable columns suit static content, while large dynamic data calls for lazy lists. [[src:cp-lists]] [[src:book-compose-tut]]')

    S = 'dsl'
    a(C + '.sec.%s.title' % S, 'DSL của LazyListScope', 'The LazyListScope DSL')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Tham số cuối của `LazyColumn` có kiểu `LazyListScope.() -> Unit`, KHÔNG phải `@Composable () -> Unit` (Tutorials Ch.4 nhấn mạnh điểm này khi đọc chữ ký hàm). Bên trong, bạn không gọi composable trực tiếp mà MÔ TẢ các mục: `item { }` một mục, `items(count)` hay `items(list)` nhiều mục, `itemsIndexed` kèm chỉ số, `stickyHeader { }` tiêu đề dính. Lambda nội dung của từng mục mới là `@Composable`, và chỉ được gọi khi lazy layout cần mục đó. [[src:book-compose-tut]] [[src:cp-lists]]', 'The last parameter of `LazyColumn` has type `LazyListScope.() -> Unit`, NOT `@Composable () -> Unit` (Tutorials Ch.4 stresses this when reading the signature). Inside, you do not call composables directly; you DESCRIBE the items: `item { }` for one, `items(count)` or `items(list)` for many, `itemsIndexed` with an index, `stickyHeader { }` for a sticky header. Each item\'s content lambda is the `@Composable` part, and it is only invoked when the lazy layout needs that item. [[src:book-compose-tut]] [[src:cp-lists]]')
    B(C, S, 2, 'kt', '// Essentials Ch.34/37: nhóm theo hãng rồi dùng stickyHeader\nval groupedPhones = phones.groupBy { it.substringBefore(\' \') }\n\nLazyColumn(\n    state = listState,\n    contentPadding = PaddingValues(bottom = 50.dp),\n    verticalArrangement = Arrangement.spacedBy(4.dp)\n) {\n    groupedPhones.forEach { (manufacturer, models) ->\n        stickyHeader { Text(manufacturer, Modifier.background(Color.Gray).padding(5.dp).fillMaxWidth()) }\n        items(models, key = { it }) { model -> MyListItem(model) }\n    }\n}', '// Essentials Ch.34/37: group by manufacturer, then stickyHeader\nval groupedPhones = phones.groupBy { it.substringBefore(\' \') }\n\nLazyColumn(\n    state = listState,\n    contentPadding = PaddingValues(bottom = 50.dp),\n    verticalArrangement = Arrangement.spacedBy(4.dp)\n) {\n    groupedPhones.forEach { (manufacturer, models) ->\n        stickyHeader { Text(manufacturer, Modifier.background(Color.Gray).padding(5.dp).fillMaxWidth()) }\n        items(models, key = { it }) { model -> MyListItem(model) }\n    }\n}')
    B(C, S, 3, 'note', '`contentPadding` thêm khoảng vào NỘI DUNG chứ không vào chính `LazyColumn`: mục đầu có khoảng trên, mục cuối có khoảng dưới, cuộn vẫn đi qua vùng đó. Tài liệu khuyên việc nhóm (`groupBy`) lý tưởng nên làm ở ViewModel. Sách (bản 1.3) đánh dấu `stickyHeader` là experimental và cần `@OptIn(ExperimentalFoundationApi::class)`; hãy kiểm tra trạng thái API ở phiên bản bạn dùng. Ví dụ trên thêm `key = { it }` mà sách không có, vì tên máy trong ví dụ là duy nhất. [[src:cp-lists]] [[src:book-compose-ess]]', '`contentPadding` adds space to the CONTENT, not to the `LazyColumn` itself: the first item gets top space, the last gets bottom space, and scrolling still passes through it. The docs suggest the grouping (`groupBy`) ideally be done in the ViewModel. The book (1.3 edition) marks `stickyHeader` as experimental, requiring `@OptIn(ExperimentalFoundationApi::class)`; check the API status in the version you use. The example above adds `key = { it }`, which the book does not, because the phone names in the example are unique. [[src:cp-lists]] [[src:book-compose-ess]]')
    B(C, S, 3, 'kind', 'source')

    S = 'inside'
    a(C + '.sec.%s.title' % S, 'Bên trong: compose trong bước đo', 'Inside: composing during measurement')
    a(C + '.sec.%s.badge' % S, 'impl')
    B(C, S, 1, 'p', 'Ở commit ghim, `LazyLayout` (nền của LazyColumn, LazyRow, grid và pager) là một `SubcomposeLayout`. KDoc nói: nó "only composes and lays out currently needed items", và việc compose một mục trong bước đo CHÍNH LÀ tín hiệu mục đó đang cần. Thường chỉ mục thấy được là cần, nhưng có thể xin thêm (prefetch). Đây là trường hợp 3 của `SubcomposeLayout` ở chương LO: compose lười theo chỗ trống. [[src:fd-lazylayout-src]] [[src:ui-subcompose-src]]', 'At the pinned commit, `LazyLayout` (the base of LazyColumn, LazyRow, grids and pagers) is a `SubcomposeLayout`. The KDoc says it "only composes and lays out currently needed items", and composing an item during measurement IS the signal that the item is needed. Usually only visible items are needed, but more can be requested (prefetching). This is case 3 of `SubcomposeLayout` from chapter LO: composing lazily by available space. [[src:fd-lazylayout-src]] [[src:ui-subcompose-src]]')
    B(C, S, 2, 'p', '`LazyLayoutItemContentFactory` giữ một cache lambda nội dung theo key: nếu một mục được subcompose lại với CÙNG instance lambda, runtime có thể skip cả mục. Mỗi mục còn được bọc trong `SaveableStateProvider` theo key, nên `rememberSaveable` trong mục được khôi phục khi mục cuộn đi rồi quay lại, hay khi Activity bị tạo lại. Khi lưu state, `LazySaveableStateHolder` chỉ lưu mục đang hiện để Bundle không phình tới `TransactionTooLargeException`. [[src:fd-lazycontent-src]] [[src:cp-lists]]', '`LazyLayoutItemContentFactory` keeps a cache of content lambdas by key: if an item is subcomposed again with the SAME lambda instance, the runtime can skip the whole item. Each item is also wrapped in a `SaveableStateProvider` by key, so `rememberSaveable` inside an item is restored when it scrolls away and back, or when the Activity is recreated. When saving state, `LazySaveableStateHolder` only saves the visible items so the Bundle does not grow into a `TransactionTooLargeException`. [[src:fd-lazycontent-src]] [[src:cp-lists]]')

    S = 'reuse'
    a(C + '.sec.%s.title' % S, 'Dùng lại slot và contentType', 'Slot reuse and contentType')
    a(C + '.sec.%s.badge' % S, 'impl')
    B(C, S, 1, 'p', 'Tutorials Ch.4 viết lazy list làm việc như RecyclerView "but without needing to recycle": mục cũ bị dispose, khi cuộn lại thì compose lại. Essentials Ch.34 cũng nói mục rời màn hình bị "destroyed". Mã ở commit ghim chính xác hơn: `SubcomposeLayout` được tạo với `LazyLayoutItemReusePolicy`. Cuối mỗi lượt đo, slot thôi được dùng không bị hủy ngay mà vào pool; chính sách giữ tối đa 7 slot cho MỖI `contentType` (chú thích trong mã: bằng RecyclerView, 5 scrap + 2 cache), phần dư mới bị dispose. Khi cần mục mới, lazy layout lấy slot trong pool nếu `areCompatible`, tức `contentType` bằng nhau, và compose nội dung mới vào đó. Hai cuốn sách mô tả đúng ý chính (chỉ compose mục thấy được) nhưng đơn giản hóa phần này. [[src:book-compose-tut]] [[src:book-compose-ess]] [[src:fd-lazylayout-src]]', 'Tutorials Ch.4 says lazy lists work like RecyclerView "but without needing to recycle": old items are disposed and recomposed when scrolled back. Essentials Ch.34 also says items leaving the screen are "destroyed". The code at the pinned commit is more precise: the `SubcomposeLayout` is created with `LazyLayoutItemReusePolicy`. At the end of each measure pass, slots no longer used are not destroyed right away but go into a pool; the policy keeps up to 7 slots PER `contentType` (the code comment: the same as RecyclerView, 5 scrap + 2 cache), and only the excess is disposed. When a new item is needed, the lazy layout takes a pooled slot if `areCompatible`, meaning the `contentType`s are equal, and composes the new content into it. Both books get the main idea right (only visible items are composed) but simplify this part. [[src:book-compose-tut]] [[src:book-compose-ess]] [[src:fd-lazylayout-src]]')
    B(C, S, 2, 'p', 'Vì vậy tài liệu khuyên: danh sách có nhiều loại mục (tiêu đề, ảnh, chữ) thì khai báo `contentType`, vì Compose chỉ dùng lại composition giữa các mục cùng loại. Mô phỏng ngay dưới đếm số lần compose từ đầu và dùng lại khi cuộn. [[src:cp-lists]]', 'Hence the docs\' advice: a list with several kinds of items (headers, images, text) should declare `contentType`, because Compose only reuses compositions between items of the same type. The simulation just below counts fresh compositions and reuses while scrolling. [[src:cp-lists]]')
    B(C, S, 3, 'predict', 'Trong kịch bản "cùng kiểu", ở frame cuộn ĐẦU TIÊN mục 4 có dùng lại slot của mục 0 không?', 'In the "same type" scenario, in the FIRST scroll frame, does item 4 reuse item 0\'s slot?')
    B(C, S, 3, 'ans', 'Không. Slot của mục 0 chỉ vào pool ở cuối lượt đo đó, sau khi mục 4 đã được compose. Từ frame thứ hai, mục mới mới lấy được slot cũ. [[src:ui-subcompose-src]]', 'No. Item 0\'s slot only enters the pool at the end of that measure pass, after item 4 has been composed. From the second frame on, new items can take old slots. [[src:ui-subcompose-src]]')

    S = 'keys'
    a(C + '.sec.%s.title' % S, 'Key: state đi theo mục', 'Keys: state follows the item')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Mặc định state của mỗi mục gắn với VỊ TRÍ. Khi dữ liệu đổi, mục đổi vị trí mất state đã remember; ví dụ của tài liệu: một `LazyRow` nằm trong `LazyColumn` mất vị trí cuộn khi hàng của nó dời chỗ. Khai báo `key` thì Compose dời state theo mục. Đây là cùng ý với `key()` trong chương B3, áp cho lazy list. [[src:cp-lists]]', 'By default each item\'s state is tied to its POSITION. When the data changes, items that move lose their remembered state; the docs\' example: a `LazyRow` inside a `LazyColumn` loses its scroll position when its row moves. Declare a `key` and Compose moves the state with the item. This is the same idea as `key()` in chapter B3, applied to lazy lists. [[src:cp-lists]]')
    B(C, S, 2, 'kt', 'LazyColumn {\n    items(\n        items = messages,\n        key = { message -> message.id }       // ổn định + duy nhất\n    ) { message ->\n        MessageRow(message)\n    }\n}', 'LazyColumn {\n    items(\n        items = messages,\n        key = { message -> message.id }       // stable + unique\n    ) { message ->\n        MessageRow(message)\n    }\n}')
    B(C, S, 3, 'p', 'Yêu cầu với key: "stable + unique", và KIỂU của key phải được `Bundle` hỗ trợ (kiểu nguyên thủy, enum, Parcelable), vì `rememberSaveable` trong mục dùng key để khôi phục khi Activity được tạo lại hoặc khi cuộn đi rồi quay lại. Key còn bắt buộc cho `Modifier.animateItem()`: không có key thì không biết mục đã dời tới đâu để animate. [[src:cp-lists]]', 'Requirements for keys: "stable + unique", and the key\'s TYPE must be supported by `Bundle` (primitives, enums, Parcelables), because `rememberSaveable` inside an item uses the key to restore when the Activity is recreated or when you scroll away and back. Keys are also required for `Modifier.animateItem()`: without them it cannot know where a moved item went in order to animate it. [[src:cp-lists]]')

    S = 'scroll'
    a(C + '.sec.%s.title' % S, 'Đọc vị trí cuộn cho đúng', 'Reading the scroll position correctly')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Essentials Ch.37 hiện nút "lên đầu" bằng `val displayButton = listState.firstVisibleItemIndex > 5` ngay trong thân composable. Cách đó chạy đúng, nhưng `firstVisibleItemIndex` được đọc trong composition, nên mỗi lần nó đổi (mỗi mục cuộn qua) cả `MainScreen` recompose, dù `displayButton` vẫn là `true`. Tài liệu bọc trong `derivedStateOf` để giảm composition không cần thiết: chỉ khi kết quả Boolean đổi thì mới invalidate (chương B4). [[src:book-compose-ess]] [[src:cp-lists]]', 'Essentials Ch.37 shows a "back to top" button with `val displayButton = listState.firstVisibleItemIndex > 5` right in the composable body. It works, but `firstVisibleItemIndex` is read in composition, so every time it changes (every item scrolled past) the whole `MainScreen` recomposes, even though `displayButton` stays `true`. The docs wrap it in `derivedStateOf` to minimise unnecessary compositions: only a change in the Boolean result invalidates (chapter B4). [[src:book-compose-ess]] [[src:cp-lists]]')
    B(C, S, 2, 'kt', 'val listState = rememberLazyListState()\nval showButton by remember {\n    derivedStateOf { listState.firstVisibleItemIndex > 0 }   // chỉ đổi khi Boolean đổi\n}\nAnimatedVisibility(visible = showButton) { ScrollToTopButton() }\n\n// hiệu ứng phụ (analytics): snapshotFlow, không recompose\nLaunchedEffect(listState) {\n    snapshotFlow { listState.firstVisibleItemIndex }\n        .map { index -> index > 0 }\n        .distinctUntilChanged()\n        .filter { it }\n        .collect { MyAnalyticsService.sendScrolledPastFirstItemEvent() }\n}', 'val listState = rememberLazyListState()\nval showButton by remember {\n    derivedStateOf { listState.firstVisibleItemIndex > 0 }   // changes only when the Boolean changes\n}\nAnimatedVisibility(visible = showButton) { ScrollToTopButton() }\n\n// side effects (analytics): snapshotFlow, no recomposition\nLaunchedEffect(listState) {\n    snapshotFlow { listState.firstVisibleItemIndex }\n        .map { index -> index > 0 }\n        .distinctUntilChanged()\n        .filter { it }\n        .collect { MyAnalyticsService.sendScrolledPastFirstItemEvent() }\n}')

    S = 'tips'
    a(C + '.sec.%s.title' % S, 'Mẹo của tài liệu', 'Tips from the docs')
    a(C + '.sec.%s.badge' % S, 'guideline')
    B(C, S, 1, 'p', 'Bản tóm tắt phần Tips của trang Lists (site đọc phần này qua bản tóm tắt, không phải nguyên văn): (1) tránh mục cao 0 px, ví dụ ảnh tải bất đồng bộ lúc đầu rỗng: lần đo đầu sẽ thấy mọi mục "vừa" viewport và compose hết; hãy cho kích thước mặc định. (2) Không lồng thứ cuộn cùng chiều không giới hạn kích thước: `LazyColumn` trong `Column(verticalScroll)` ném `IllegalStateException` (khác chiều thì được; cùng chiều được nếu con có kích thước cố định); hãy gom header/footer vào cùng một `LazyColumn` bằng `item { }`. (3) Không gộp nhiều phần tử vào một `item { }`: chúng thành một khối, không compose riêng được và làm sai `scrollToItem`; divider là ngoại lệ chấp nhận được. (4) Khai báo `contentType`. (5) Đo hiệu năng ở bản release có R8; bản debug cuộn có thể chậm hơn. [[src:cp-lists]]', 'A summary of the Lists page\'s Tips section (the site read this section through a summary, not verbatim): (1) avoid 0-pixel items, for example asynchronously loaded images that start empty: the first measurement sees every item "fit" the viewport and composes them all; give them a default size. (2) Do not nest same-direction scrollables without a bounded size: a `LazyColumn` inside a `Column(verticalScroll)` throws `IllegalStateException` (different directions are fine; the same direction works if the child has a fixed size); put header/footer into the same `LazyColumn` with `item { }`. (3) Do not put several elements into one `item { }`: they become one block, cannot be composed separately and break `scrollToItem`; dividers are an accepted exception. (4) Declare `contentType`. (5) Measure performance in a release build with R8; debug builds may scroll slower. [[src:cp-lists]]')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Xóa một mục khỏi danh sách việc cần làm, và dấu tick "đã xong" nhảy sang mục bên dưới.', 'Deleting an item from a to-do list makes the "done" tick jump to the item below.')
    B(C, S, 1, 'cause', 'Không có `key`: state `remember` gắn với vị trí. Mục phía dưới dồn lên vị trí cũ và nhận state đó.', 'No `key`: `remember` state is tied to position. The item below moves up into the old position and inherits that state.')
    B(C, S, 1, 'fix', '`items(todos, key = { it.id })`, hoặc tốt hơn, giữ cờ "đã xong" trong dữ liệu (state hoisting, chương SH). [[src:cp-lists]]', '`items(todos, key = { it.id })`, or better, keep the "done" flag in the data (state hoisting, chapter SH). [[src:cp-lists]]')
    B(C, S, 2, 'bug', 'App crash khi mở màn hình: "Vertically scrollable component was measured with an infinity maximum height constraints…".', 'The app crashes when opening a screen: "Vertically scrollable component was measured with an infinity maximum height constraints…".')
    B(C, S, 2, 'cause', 'Một `LazyColumn` nằm trong `Column(Modifier.verticalScroll(…))`. Cột cuộn cho con chiều cao tối đa vô hạn (chương LO), còn lazy list cần chiều cao có giới hạn để biết bao nhiêu mục vừa. Thông điệp lỗi ở trên là của `checkScrollableContainerConstraints` ở commit ghim. [[src:fd-scrollcheck-src]]', 'A `LazyColumn` sits inside a `Column(Modifier.verticalScroll(…))`. The scrolling column gives its children an infinite maximum height (chapter LO), while a lazy list needs a bounded height to know how many items fit. The error message above comes from `checkScrollableContainerConstraints` at the pinned commit. [[src:fd-scrollcheck-src]]')
    B(C, S, 2, 'fix', 'Gộp phần đầu và phần cuối vào cùng `LazyColumn` bằng `item { }`, hoặc cho lazy list chiều cao cố định nếu thật cần lồng. [[src:cp-lists]]', 'Fold the header and footer into the same `LazyColumn` with `item { }`, or give the lazy list a fixed height if nesting is truly needed. [[src:cp-lists]]')
    B(C, S, 3, 'bug', 'Danh sách tin tức cuộn giật ở những chỗ chuyển giữa thẻ ảnh lớn và thẻ chữ.', 'A news list stutters where it switches between big photo cards and text cards.')
    B(C, S, 3, 'cause', 'Không có `contentType`, nên một slot của thẻ chữ có thể được dùng cho thẻ ảnh: composition được dùng lại nhưng gần như cả cây phải dựng lại.', 'No `contentType`, so a text card\'s slot can be used for a photo card: the composition is reused, but almost the whole tree must be rebuilt.')
    B(C, S, 3, 'fix', '`items(news, key = { it.id }, contentType = { it.kind })`. Đo lại ở bản release. [[src:cp-lists]] [[src:fd-lazylayout-src]]', '`items(news, key = { it.id }, contentType = { it.kind })`. Measure again in a release build. [[src:cp-lists]] [[src:fd-lazylayout-src]]')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Viết lại cho đúng: màn hình có một ảnh bìa, rồi 200 bình luận, rồi nút "Tải thêm".', 'Rewrite this correctly: a screen with a cover image, then 200 comments, then a "Load more" button.')
    B(C, S, 1, 'exkt', 'Column(Modifier.verticalScroll(rememberScrollState())) {\n    Cover()\n    LazyColumn {\n        items(comments) { CommentRow(it) }\n    }\n    LoadMoreButton()\n}')
    B(C, S, 1, 'hint', 'Mọi thứ đều có thể là một mục của cùng một LazyColumn.', 'Everything can be an item of the same LazyColumn.')
    B(C, S, 1, 'solkt', 'LazyColumn {\n    item(contentType = "cover") { Cover() }\n    items(comments, key = { it.id }, contentType = { "comment" }) { CommentRow(it) }\n    item(contentType = "more") { LoadMoreButton() }\n}')
    B(C, S, 1, 'sol', 'Không còn lồng cuộn cùng chiều, 200 bình luận được compose lười, mỗi loại có `contentType` riêng.', 'No more same-direction nesting, the 200 comments are composed lazily, and each kind has its own `contentType`.')
    B(C, S, 2, 'ex', 'Một danh sách 100 mục cùng loại, mỗi lần cuộn qua đúng một mục. Theo mô hình của sim (bỏ qua prefetch), sau 10 lần cuộn có bao nhiêu lần compose từ đầu, bao nhiêu lần dùng lại? Viewport vừa 4 mục.', 'A list of 100 items of one kind, scrolling exactly one item at a time. Under the sim\'s model (ignoring prefetching), after 10 scrolls how many fresh compositions and how many reuses are there? The viewport fits 4 items.')
    B(C, S, 2, 'hint', 'Lần đầu compose 4. Frame cuộn 1 pool rỗng. Từ frame 2 trở đi?', 'The first pass composes 4. Scroll frame 1 has an empty pool. From frame 2 on?')
    B(C, S, 2, 'sol', '5 compose từ đầu (4 lúc đầu + 1 ở frame 1), 9 lần dùng lại (frame 2 tới 10), pool luôn còn 1 slot.', '5 fresh compositions (4 initially + 1 in frame 1), 9 reuses (frames 2 to 10), and the pool always holds 1 slot.')
    B(C, S, 3, 'ex', 'Sửa đoạn này để `MainScreen` không recompose mỗi khi cuộn qua một mục:', 'Fix this so `MainScreen` does not recompose every time an item scrolls past:')
    B(C, S, 3, 'exkt', '@Composable\nfun MainScreen(items: List<String>) {\n    val listState = rememberLazyListState()\n    val displayButton = listState.firstVisibleItemIndex > 5\n    Box {\n        LazyColumn(state = listState) { items(items) { Text(it) } }\n        if (displayButton) ScrollTopButton(listState)\n    }\n}')
    B(C, S, 3, 'hint', 'Bọc phép so sánh trong `derivedStateOf` và `remember` nó.', 'Wrap the comparison in `derivedStateOf` and `remember` it.')
    B(C, S, 3, 'solkt', 'val displayButton by remember {\n    derivedStateOf { listState.firstVisibleItemIndex > 5 }\n}')
    B(C, S, 3, 'sol', 'Giờ `MainScreen` chỉ đọc một derived state Boolean; nó chỉ invalidate khi kết quả đổi từ false sang true hay ngược lại. Thêm `key` cho `items` cũng là thói quen tốt.', 'Now `MainScreen` only reads a derived Boolean state; it only invalidates when the result flips between false and true. Adding a `key` to `items` is also a good habit.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'LazyColumn compose mục ở phase nào?', 'In which phase does a LazyColumn compose its items?')
    B(C, S, 1, 'ans', 'Trong bước đo của layout, nhờ SubcomposeLayout.', 'During the layout\'s measure step, via SubcomposeLayout.')
    B(C, S, 2, 'ask', 'Slot của mục rời màn hình đi đâu?', 'Where does the slot of an item leaving the screen go?')
    B(C, S, 2, 'ans', 'Vào pool dùng lại (tối đa 7 mỗi contentType ở commit ghim); phần dư mới bị dispose.', 'Into the reuse pool (up to 7 per contentType at the pinned commit); only the excess is disposed.')
    B(C, S, 3, 'ask', 'Kiểu của key phải thỏa điều kiện gì, và vì sao?', 'What must a key\'s type satisfy, and why?')
    B(C, S, 3, 'ans', 'Được Bundle hỗ trợ, vì rememberSaveable trong mục dùng key để lưu và khôi phục state.', 'Be supported by Bundle, because rememberSaveable inside items uses the key to save and restore state.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Không có key, chèn một mục lên đầu thì state remember của mục cũ đi đâu?', 'Without keys, where does an old item\'s remembered state go when an item is inserted at the top?',
         'Ở lại vị trí, sang mục khác.', 'It stays at the position, on another item.', 'Mặc định state gắn với vị trí.', 'By default state is tied to position.'),
        ('q2', 'Khi nào slot trong pool được dùng cho mục mới?', 'When is a pooled slot used for a new item?',
         'Khi contentType bằng nhau.', 'When the contentTypes are equal.', 'areCompatible chỉ so contentType.', 'areCompatible only compares contentType.'),
        ('q3', 'LazyColumn trong Column(verticalScroll) không giới hạn chiều cao thì sao?', 'What happens to a LazyColumn inside an unbounded Column(verticalScroll)?',
         'Ném IllegalStateException.', 'It throws IllegalStateException.', 'Lazy list cần chiều cao tối đa có giới hạn.', 'A lazy list needs a bounded maximum height.'),
        ('q4', 'Đọc `firstVisibleItemIndex > 0` để hiện nút: nên viết thế nào?', 'Reading `firstVisibleItemIndex > 0` to show a button: how should it be written?',
         'Bọc trong remember { derivedStateOf { … } }.', 'Wrap it in remember { derivedStateOf { … } }.', 'Chỉ invalidate khi Boolean đổi.', 'Only invalidates when the Boolean changes.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
